function bitcrushProcess(samples, opts){
  opts = opts || {};
  var bits = opts.bits != null ? opts.bits : 8;       // 1..16
  var dsRatio = opts.downsample != null ? opts.downsample : 1; // >=1
  if(bits<1) bits=1; if(bits>16) bits=16;
  if(dsRatio<1) dsRatio=1;
  var levels = Math.pow(2, bits);
  var out = new Array(samples.length);
  var hold = 0, holdIdx = 0;
  for(var i=0;i<samples.length;i++){
    var s = samples[i];
    if(dsRatio>1){ if(i % dsRatio === 0) hold = s; s = hold; }
    // 量化到 bits 位深
    var q = Math.round((s+1)/2 * (levels-1)) / (levels-1) * 2 - 1;
    if(q < -1) q = -1; if(q > 1) q = 1;
    out[i] = q;
  }
  return out;
}
function bitcrushAnalyze(samples, opts){
  var out = bitcrushProcess(samples, opts);
  var peak=0,sum=0,distinct={};
  for(var i=0;i<out.length;i++){ var a=Math.abs(out[i]); if(a>peak)peak=a; sum+=out[i]*out[i]; distinct[out[i].toFixed(6)]=1; }
  return { length:out.length, peak:peak, rms:Math.sqrt(sum/out.length), distinctLevels:Object.keys(distinct).length };
}

var EXPORTS={bitcrushProcess:bitcrushProcess,bitcrushAnalyze:bitcrushAnalyze};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.BitcrushForgePure = EXPORTS; }
